const verified=Symbol('v92 exact source'),skip=Symbol('v92 native clause');
const equal=(a,b)=>JSON.stringify(a)===JSON.stringify(b);
export function normalizeCard(card,original){const source=SOURCES[original.name];return {...card,[verified]:source&&Object.entries(source).every(([k,v])=>equal(original[k],v))?original.name:null};}
const op=(name,clauses)=>({kind:'complete-face-v92',name,clauses,contract:'generic-continuous-effect'});
function compileFace(face,physical,h){
 const normal={...physical,...face,layout:'normal',card_faces:undefined,[skip]:true};
 for(const key of ['power','toughness','loyalty','defense'])if(face[key]===undefined)delete normal[key];
 const core=h.stripReminderText(face.oracle_text||'');
 if(face.name==='Comet, Stellar Pup')return {semanticClass:'permanent-template',implementation:[op(face.name,[core])],implementedKeywords:[],oracleContracts:['generic-activated-effect','generic-continuous-effect'],rulesCore:core};
 const full=h.compileCurrent({...normal,oracle_text:core});
 let result;
 if(full.semanticClass)result=full;
 else{
  const implementation=[],clauses=[],implementedKeywords=[],contracts=new Set();
  const paragraphs=[];for(const line of core.split('\n').filter(Boolean)){if(line.startsWith('• ')&&paragraphs.length)paragraphs[paragraphs.length-1]+='\n'+line;else paragraphs.push(line);}
  for(const line of paragraphs){const r=h.compileCurrent({...normal,oracle_text:line});if(r.semanticClass){implementation.push(...r.implementation);implementedKeywords.push(...r.implementedKeywords||[]);for(const c of r.oracleContracts||[])contracts.add(c);}else clauses.push(line);}
  if(clauses.length){implementation.push(op(face.name,clauses));for(const c of ['generic-trigger-effect','generic-activated-effect','generic-continuous-effect'])contracts.add(c);}
  result={semanticClass:face.type_line.includes('Creature')?'creature-template':/\b(?:Instant|Sorcery)\b/.test(face.type_line)?'spell-template':'permanent-template',implementation,implementedKeywords:[...new Set(implementedKeywords)],oracleContracts:[...contracts]};
 }
 if(/\bBattle\b/.test(face.type_line)){result.implementation.push({kind:'siege-rules-v92',contract:'generic-trigger-effect'});result.oracleContracts=[...new Set([...result.oracleContracts,'generic-trigger-effect'])];}
 return {...result,rulesCore:core};
}
export function compileWholeCard(card,h){
 if(card[skip])return null;const physical=SOURCES[card[verified]];if(!physical)return null;
 if(!physical.card_faces)return compileFace(physical,physical,h);
 const faces=physical.card_faces.map((face,i)=>({key:i?'back':'front',raw:{...h.raw({...physical,...face,layout:'normal',card_faces:undefined}),colorsOverride:face.color_indicator||face.colors||[]},...compileFace(face,physical,h)}));
 return {semanticClass:'permanent-template',implementation:[{kind:'double-faced-v8',layout:'transform',faces,contract:'double-faced-card'}],implementedKeywords:[],oracleContracts:['double-faced-card'],rulesCore:faces.map(f=>f.raw.name+': '+f.rulesCore).join('\n')};
}
